/*
 * MegaNetLedgerAd — 1080x1920 @30fps, ~19s (0.4s lead-in, voice 16.6s, 2s frozen hold).
 * Voice: public/voiceover-ledger.mp3 (en-NG-AbeoNeural), word timings in src/ledgerTimings.ts
 * (both generated by scripts/ledger_voice.py). Shared helpers (gradients, drawn icons, debug layers) come from src/fx.tsx.
 *
 * Look: light and airy. Brand blue #1A6DE0 + orange #F7941D on near-white / pale blue / pale peach gradients, white cards,
 * dark charcoal text, green/red/teal accents. See STYLE_GUIDE.md for the rules (contrast >= 4.5:1, labels >= 32px).
 *
 * Safe area: all content inside x 80-920, y 200-1440; captions end at y=1340 (limit 1360). Every scene (and its
 * header) lives inside a clip box of exactly the safe area, so slides and wipes can never leave it.
 * Transitions are slides and wipes, not fades: slide-left, wipe-up, slide-right, diagonal wipe, slide-up.
 *
 * Debug input prop (verification only): 'bg' = gradients only, 'caps' = captions only, 'violate-*' / 'violateweak-left'
 * = negative controls, 'audit' = logs every text node's box/colour/size, 'notext' = same frame with text made transparent.
 *
 * No figures, names or statistics: rows, chips and bars are drawn placeholders.
 */
import React, {useEffect, useState} from 'react';
import {AbsoluteFill, Audio, Easing, Freeze, Img, Sequence, continueRender, delayRender, interpolate, staticFile, useCurrentFrame} from 'remotion';
import {LINES, VOICE_END} from './ledgerTimings';
import {DebugContext, Icon as FxIcon, Layer, GradientBg, Glow} from './fx';

export const LEDGER_FPS = 30;
const LEAD = 12; // 0.4s before the voice starts
const FREEZE = LEAD + Math.round(VOICE_END * LEDGER_FPS); // last frame with any motion
export const LEDGER_DURATION = FREEZE + 2 * LEDGER_FPS; // hold 2s after the voice ends

// palette (fills) and text-safe variants (>= 4.5:1 on white and on the pale backgrounds)
const BLUE = '#1A6DE0';
const ORANGE = '#F7941D';
const GREEN = '#12875A';
const RED = '#D8383D';
const TEAL = '#0E9AA7';
const LAV = '#9B8CF5';
const TXT_BLUE = '#1458B5';
const TXT_ORANGE = '#9E3F00';
const TXT_GREEN = '#0B6E46';
const TXT_RED = '#B42328';
const TXT_TEAL = '#0A6A74';
const INK = '#1B2430';
const MUTED = '#44506A';
const WHITE = '#FFFFFF';
const FONT = 'Inter, "Inter Display", system-ui, sans-serif';

const COL_L = 110;
const COL_W = 780; // x 110-890, inside the 80-920 safe area
const SAFE = {x: 80, y: 200, w: 840, h: 1240};

const wordF = (s: number, w: number) => LEAD + Math.round(LINES[s].words[w].start * LEDGER_FPS);
const sceneFrom = (i: number) => (i === 0 ? 0 : wordF(i, 0) - 5);
const TR = 10; // transition length in frames
const LAST = LINES.length - 1;
const sceneTo = (i: number) => (i === LAST ? LEDGER_DURATION : sceneFrom(i + 1) + TR);

const ease = Easing.out(Easing.cubic);
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const enter = (l: number, start: number, dur = 9) =>
  interpolate(l, [start, start + dur], [0, 1], {easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
const rise = (v: number) => `translateY(${(1 - v) * 36}px)`;

/* ---------- transitions between scenes ---------- */

type Trans = 'slide-left' | 'wipe-up' | 'slide-right' | 'diag' | 'slide-up';
const TRANS: (Trans | null)[] = [null, 'slide-left', 'wipe-up', 'slide-right', 'diag', 'slide-up'];
const progress = (f: number, from: number) => ease(clamp01((f - from) / TR));
const diagMask = (q: number, invert: boolean) => {
  const a = `${(q * 100).toFixed(2)}%`;
  const b = `${Math.min(100, q * 100 + 0.4).toFixed(2)}%`;
  const g = invert ? `linear-gradient(135deg, transparent ${a}, #000 ${b})` : `linear-gradient(135deg, #000 ${a}, transparent ${b})`;
  return {maskImage: g, WebkitMaskImage: g} as React.CSSProperties;
};
/** Style for a scene's content layer (full-canvas coordinates, inside the safe-area clip box). */
const contentStyle = (t: Trans | null, p: number, dir: 'in' | 'out'): React.CSSProperties => {
  if (!t) return {};
  const q = dir === 'in' ? 1 - p : p; // 0 = settled, 1 = fully away
  switch (t) {
    case 'slide-left':
      return {transform: `translateX(${dir === 'in' ? q * SAFE.w : -q * SAFE.w}px)`};
    case 'slide-right':
      return {transform: `translateX(${dir === 'in' ? -q * SAFE.w : q * SAFE.w}px)`};
    case 'slide-up':
      return {transform: `translateY(${dir === 'in' ? q * SAFE.h : -q * SAFE.h}px)`};
    case 'wipe-up':
      return dir === 'in' ? {clipPath: `inset(${q * 100}% 0 0 0)`, transform: `translateY(${q * 40}px)`} : {clipPath: `inset(0 0 ${q * 100}% 0)`};
    case 'diag':
      return dir === 'in' ? diagMask(p, false) : diagMask(p, true);
  }
};
/** Style for the incoming scene's full-bleed background reveal. */
const bgStyle = (t: Trans | null, p: number): React.CSSProperties => {
  if (!t) return {};
  const q = 1 - p;
  switch (t) {
    case 'slide-left':
      return {clipPath: `inset(0 0 0 ${q * 100}%)`};
    case 'slide-right':
      return {clipPath: `inset(0 ${q * 100}% 0 0)`};
    case 'slide-up':
    case 'wipe-up':
      return {clipPath: `inset(${q * 100}% 0 0 0)`};
    case 'diag':
      return diagMask(p, false);
  }
};

/* ---------- backgrounds: one distinct light gradient per scene (full bleed, content-free) ---------- */

const g = (x: number, y: number, r: number, color: string, drift = 30): Glow => ({x, y, r, color, drift});
const BGS: {stops: string[]; angle: number; glows: Glow[]}[] = [
  {stops: ['#FFFFFF', '#E4F0FF', '#FFE9CE'], angle: 160, glows: [g(180, 420, 460, 'rgba(26,109,224,0.16)'), g(930, 1500, 500, 'rgba(247,148,29,0.22)')]},
  {stops: ['#FFF8EE', '#FFE3BE', '#D9E9FF'], angle: 200, glows: [g(900, 400, 440, 'rgba(247,148,29,0.24)'), g(150, 1560, 500, 'rgba(26,109,224,0.16)')]},
  {stops: ['#EAF4FF', '#CBE2FF', '#FFF0D9'], angle: 170, glows: [g(160, 430, 440, 'rgba(14,154,167,0.16)'), g(920, 1450, 500, 'rgba(247,148,29,0.2)')]},
  {stops: ['#FFF4E4', '#FFDCAE', '#E4EEFF'], angle: 150, glows: [g(900, 420, 440, 'rgba(26,109,224,0.14)'), g(160, 1500, 480, 'rgba(247,148,29,0.26)')]},
  {stops: ['#E2EEFF', '#BFD9FF', '#FFEFD6'], angle: 190, glows: [g(170, 420, 440, 'rgba(255,255,255,0.5)'), g(920, 1500, 500, 'rgba(247,148,29,0.2)')]},
  {stops: ['#D4E6FF', '#FFF3E0', '#FFC584'], angle: 150, glows: [g(200, 380, 460, 'rgba(255,255,255,0.55)'), g(900, 1450, 500, 'rgba(247,148,29,0.28)')]},
];

const Backgrounds: React.FC = () => {
  const f = useCurrentFrame();
  return (
    <AbsoluteFill>
      {BGS.map((b, i) => {
        const from = sceneFrom(i);
        if (f < from) return null;
        const p = i === 0 ? 1 : progress(f, from);
        return (
          <Sequence key={i} from={from} durationInFrames={LEDGER_DURATION - from} layout="none">
            <AbsoluteFill style={bgStyle(TRANS[i], p)}>
              <GradientBg stops={b.stops} angle={b.angle} glows={b.glows} />
            </AbsoluteFill>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

/* ---------- small drawn pieces ---------- */

