const Scene3: React.FC<{l: number}> = ({l}) => {
  const w = (n: number) => wordF(2, n) - sceneFrom(2);
  const card = enter(l, 2, 10);
  const colState = COLS.map((c) => {
    const start = w(c.word);
    const on = enter(l, start - 3, 6);
    const pulse = l >= start - 3 && l < start + 22 ? 0.5 + 0.5 * Math.sin((l - start) / 3.2) : 0;
    return {on, pulse};
  });
  return (
    <Card style={{top: 380, padding: '26px 24px 30px', opacity: card, transform: rise(card)}}>
      <div style={{position: 'relative', width: 732}}>
        {COLS.map((c, i) => (
          <div key={c.label} style={{position: 'absolute', left: c.x, width: c.w, top: -8, bottom: -8, borderRadius: 22, background: c.color, opacity: colState[i].on * (0.1 + 0.12 * colState[i].pulse)}} />
        ))}
        <div style={{position: 'relative', display: 'flex', height: 88, alignItems: 'center'}}>
          {COLS.map((c) => (
            <div key={c.label} style={{width: c.w, fontSize: 32, lineHeight: 1.08, fontWeight: 900, color: c.txt, paddingLeft: 8, whiteSpace: c.label === 'Running balance' ? 'normal' : 'nowrap'}}>
              {c.label}
            </div>
          ))}
        </div>
        <StatementRow label="Opening balance" tint={BLUE} l={l} delay={6} />
        {ROWS.map((r, i) => {
          const t = enter(l, 12 + i * 6, 8);
          return (
            <div key={i} style={{position: 'relative', display: 'flex', height: 88, alignItems: 'center', opacity: t, transform: `translateX(${(1 - t) * 40}px)`, borderTop: '2px solid #E1E8F5'}}>
              <div style={{width: 196, paddingLeft: 8}}>
                <div style={{width: r.ref, height: 34, borderRadius: 17, background: `${BLUE}22`, border: `3px solid ${BLUE}66`, boxSizing: 'border-box'}} />
              </div>
              <div style={{width: 138, paddingLeft: 8}}>{r.side === 'debit' && <Chip color={GREEN} w={r.amt} />}</div>
              <div style={{width: 150, paddingLeft: 8}}>{r.side === 'credit' && <Chip color={RED} w={r.amt} />}</div>
              <div style={{width: 248, paddingLeft: 8}}>
                <Bar w={r.bal * t} h={28} color={TEAL} alpha="BB" />
              </div>
            </div>
          );
        })}
        <StatementRow label="Closing balance" tint={ORANGE} l={l} delay={40} />
      </div>
    </Card>
  );
};

